/// </summary>
public class METALMSupplierVolumetricRebateLine extends common
{  
}

Method.Source:
    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Inits the METALMSupplierVolumetricRebateLine fields with default values.
    /// </summary>
    public void initValue()
    {
        super();

        this.CustVend = CustVendACType::Vend;
    }

/// <summary>
/// MPJ-5904, GVivanco, 26Jun2021
/// Inits the METALMSupplierVolumetricRebateLine fields with values from 
/// a METALMSupplierVolumetricRebateHeader record
/// </summary>
/// <param name = "_header">METALMSupplierVolumetricRebateHeader record</param>
public void initFromALMSupplierVolumetricRebateHeader(METALMSupplierVolumetricRebateHeader _header)
{
    this.ALMSupplierVolumetricRebateNumber = _header.Number;
    this.FinancialDimension = _header.FinancialDimension;
    this.setDimensions(_header);
}

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Insert method for METALMSupplierVolumetricRebateLine records
    /// </summary>
    public void insert()
    {
        if (!this.LineNumber)
        {
            this.LineNumber = METALMSupplierVolumetricRebateLine::lastLineNumber(
                        this.ALMSupplierVolumetricRebateNumber) + 1;
        }

        super();
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 02Jul2021
    /// Checks on populated fields according to ALM SVR type and CustVend fields
    /// </summary>
    /// <returns>true if fields are populated properly</returns>
    public boolean validatePopulatedFields()
    {
        if (this.header().Type == METALMSupplierVolumetricRebateType::SVR
            || this.CustVend == CustVendACType::Cust)
        {
            if ((!this.LedgerDimension && this.header().CustLegalEntity == curExt()) 
                    || this.ProcurementCategory)
            {
                return checkFailed("@MET:ALMSVRMainAccountPopulated");
            }
        }
        else if(this.header().Type == METALMSupplierVolumetricRebateType::RDA
            && this.CustVend == CustVendACType::Vend)
        {
            if (!this.ProcurementCategory || this.LedgerDimension)
            {
                return checkFailed("@MET:ALMSVRProcurementCategoryPopulated");
            }
        }   

        if((this.header().CustLegalEntity == curExt() || this.CustVend == CustVendACType::Vend)
            && !this.FinancialDimension)
        {
            return  checkFailed("@MET:FinancialDimNotSet");
        }
    
        return true;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// ValidateWrite method for METALMSupplierVolumetricRebateLine records
    /// </summary>
    /// <returns>true if the record passes the validation, false otherwise</returns>
    public boolean validateWrite()
    {
        boolean ret;

        if(System.String::IsNullOrEmpty(this.Description))
        {
            this.Description = this.defaultDescription();
        }
    
        ret = super();

        ret = ret && this.header().validateStatus();

        ret = ret && this.validatePopulatedFields();
    
        return ret;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// ValidateDelete method for METALMSupplierVolumetricRebateLine records
    /// </summary>
    /// <returns>true if it passes the validation, otherwise false</returns>
    public boolean validateDelete()
    {
        boolean ret;
    
        ret = super();

        ret = ret && this.header().validateStatus();
    
        return ret;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Find method for <t>METALMSupplierVolumetricRebateLine</t>
    /// </summary>
    /// <param name = "_number">METALMSupplierVolumetricRebate Number</param>
    /// <param name = "_lineNumber">Line number</param>
    /// <param name = "_forupdate">boolean forUpdate</param>
    /// <returns>A METALMSupplierVolumetricRebateLine if found, otherwise null</returns>
    static METALMSupplierVolumetricRebateLine find(
                METALMSupplierVolumetricRebateNumber _number,
                LineNum _lineNumber,
                boolean _forupdate = false)
    {
        METALMSupplierVolumetricRebateLine line;

        if (_lineNumber && _number != '')
        {
            line.selectForUpdate(_forupdate);

            select firstonly line
                where   line.ALMSupplierVolumetricRebateNumber == _number
                &&  line.LineNumber == _lineNumber;
        }
        
        return line;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// FindRecId method for <t>METALMSupplierVolumetricRebateLine</t>
    /// </summary>
    /// <param name = "_recId">RecId</param>
    /// <param name = "_forupdate">boolean forUpdate</param>
    /// <returns>A METALMSupplierVolumetricRebateLine if found, otherwise null</returns>
    static METALMSupplierVolumetricRebateLine findRecId(
                        RecId _recId,
                        boolean _forupdate = false)
    {
        METALMSupplierVolumetricRebateLine line;

        if (_recId)
        {
            line.selectForUpdate(_forupdate);

            select firstonly line
                where line.RecId == _recId;
        }
        
        return line;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Exist method for <t>METALMSupplierVolumetricRebateLine</t>
    /// </summary>
    /// <param name = "_number">ALMSupplierVolumetricRebate Number</param>
    /// <param name = "_lineNumber">Line number</param>
    /// <returns>true is record is found, false otherwise</returns>
    static boolean exist(METALMSupplierVolumetricRebateNumber _number,
                        LineNum _lineNumber)
    {
        boolean found;

        found = (select firstonly RecId from
            METALMSupplierVolumetricRebateLine
            where
            METALMSupplierVolumetricRebateLine.ALMSupplierVolumetricRebateNumber == _number
            && METALMSupplierVolumetricRebateLine.LineNumber == _lineNumber)
            .RecId != 0;
         
        return found;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Calculates the value of the last LineNumber inserted for a
    /// ALMSupplierVolumetricRebate
    /// </summary>
    /// <param name = "_number">ALMSupplierVolumetricRebate Number</param>
    /// <returns>last Line number</returns>
    public static LineNum lastLineNumber(METALMSupplierVolumetricRebateNumber _number)
    {
        METALMSupplierVolumetricRebateLine line;

        if (_number)
        {
            select maxof(LineNumber) from line
                where line.ALMSupplierVolumetricRebateNumber == _number;
        }

        return line.LineNumber;
    }

/// <summary>
/// MPJ-5904, GVivanco, 26Jun2021
/// Finds the header associated to a METALMSupplierVolumetricRebateLine
/// record
/// </summary>
/// <returns>A METALMSupplierVolumetricRebateHeader record is found,
/// otherwise null</returns>
public METALMSupplierVolumetricRebateHeader header()
{
    return METALMSupplierVolumetricRebateHeader::find(this.ALMSupplierVolumetricRebateNumber);
}

    /// <summary>
    /// MPJ-5904, GVivanco, 02Jul2021
    /// ModifiedField method for METALMSupplierVolumetricRebateLine records
    /// </summary>
    /// <param name = "_fieldId">The field ID for the modified field.</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        if (_fieldId == fieldNum(METALMSupplierVolumetricRebateLine, CustVend))
        {
            this.setDimensions();
        }
    }

    /// <summary>
    /// This method will set financial dimensions based on type.
    /// </summary>
    /// <param name = "_header">Record of type METALMSupplierVolumetricRebateHeader</param>
    public void setDimensions(METALMSupplierVolumetricRebateHeader _header = this.header())
    {
        VendParameters                          vendParameters = VendParameters::find();

        if (_header.Type == METALMSupplierVolumetricRebateType::SVR)
        {
            this.LedgerDimension        = vendParameters.METSVRLedgerDimension;
            this.ProcurementCategory    = 0;
        }
        else if(_header.Type == METALMSupplierVolumetricRebateType::RDA
            && this.CustVend == CustVendACType::Cust)
        {
            this.LedgerDimension        = vendParameters.METRDALedgerDimension;
            this.ProcurementCategory    = 0;
        }
        else if(_header.Type == METALMSupplierVolumetricRebateType::RDA
            && this.CustVend == CustVendACType::Vend)
        {
            this.LedgerDimension        = 0;
            this.ProcurementCategory    = vendParameters.METRDAProcurementCategory;
        }

        if(this.CustVend    == CustVendACType::Cust && _header.CustLegalEntity != curExt())
        {
            // Clear financial & ledger dimensions and assign at the time of creating Free text invoice
            this.FinancialDimension = 0;
            this.LedgerDimension    = 0;
        }
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 02Jul2021
    /// Calculates the total sum Amount from the vendor lines for a given ALM Supplier Volumetric
    /// Rebate number
    /// </summary>
    /// <param name = "_number">ALM Supplier volumetric rebate number</param>
    /// <returns>The calculated amount</returns>
    static AmountCur totalVendAmount(METALMSupplierVolumetricRebateNumber _number)
    {
        METALMSupplierVolumetricRebateLine line;

        select sum(Amount) from line
            where   line.ALMSupplierVolumetricRebateNumber == _number
            &&  line.CustVend == CustVendACType::Vend;
   
        return line.Amount;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 02Jul2021
    /// Returns a default description according to the type of Rebate
    /// </summary>
    /// <returns>default description</returns>
    public TransactionTextLarge defaultDescription()
    {
        if (this.header().Type == METALMSupplierVolumetricRebateType::SVR)
        {
            return "@MET:ALMSVR";
        }

        return "@MET:ALMRDA";
    }
